      return false unless stream.serialize_compressed_float_precomputed(_s_rf, 10000, 14, 10.0, -5.0)
      self.offset = _s_rf.value
      true
    end

    def _s_write(stream)
      _s_rf = Serialize::Ref.new(0.0)
      _s_rf.value = self.boundary
      stream.serialize_compressed_float_precomputed(_s_rf, 1000, 10, 10.0, 0.0)
      _s_rf.value = self.offset
      stream.serialize_compressed_float_precomputed(_s_rf, 10000, 14, 10.0, -5.0)
      nil
    end

    def _s_validate(path)
      _s_v1 = self.boundary #: untyped
      unless _s_v1.is_a?(::Float) && _s_v1 >= 0.0 && _s_v1 <= 10.0
        ::Example._s_validate_compressed_float(_s_v1, "#{path}.boundary", 0.0, 10.0)
      end
      _s_v2 = self.offset #: untyped
      unless _s_v2.is_a?(::Float) && _s_v2 >= -5.0 && _s_v2 <= 5.0
        ::Example._s_validate_compressed_float(_s_v2, "#{path}.offset", -5.0, 5.0)
      end
      nil
    end

    def _s_zero
      self.boundary = 0.0
      self.offset = 0.0
      nil
    end

  end
end
